import{_ as t,c as a,o,ak as n}from"./chunks/framework.DWj_FwGv.js";const p=JSON.parse('{"title":"Open Telemetry","description":"Tracing and metrics with Opentelemetry in PURISTA typescript nodejs backend framework applications and how to use them.","frontmatter":{"title":"Open Telemetry","description":"Tracing and metrics with Opentelemetry in PURISTA typescript nodejs backend framework applications and how to use them.","order":400000},"headers":[],"relativePath":"handbook/4_open_telemetry/index.md","filePath":"handbook/4_open_telemetry/index.md","lastUpdated":1770384944000}'),i={name:"handbook/4_open_telemetry/index.md"};function s(r,e,c,l,h,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="open-telemetry" tabindex="-1">Open Telemetry <a class="header-anchor" href="#open-telemetry" aria-label="Permalink to “Open Telemetry”">​</a></h1><p>PURISTA has built-in support for <a href="https://opentelemetry.io/" target="_blank" rel="noreferrer">OpenTelemetry</a> and it is deeply integrated into the framework.</p><p>This means there is an industry-standard way of tracing and metrics out of the box. This not only allows you to use third-party applications for analysis and alerting. It is also a huge benefit when it comes to integration. This enables you to trace and collect metrics across your whole setup and not be restricted only to the PURISTA part.</p><h2 id="tracing" tabindex="-1">Tracing <a class="header-anchor" href="#tracing" aria-label="Permalink to “Tracing”">​</a></h2><p>Traceability becomes essential when something does not work as expected.</p><p>One kind of issues are the ones, which are the more technical ones. Some function is throwing some error. In other software designs, you often end up with some code line number, and you start digging into the code, follow all the logic through a lot of files. You jump from one abstraction to the next one. You check wrapper by wrapper, interfaces and all that stuff. This can become quite challenging, if for example in production only bundled and compiled javascript code is deployed. In this case line numbers and even function names might completely differ from your source typescript code.</p><p>The other kind of issues are even harder to track: things work from a technical point of view, but not from a business point of view. In this case, you need to walk through the code logic, and check if the business logic is matching the implementation logic. And depending on your abstractions, layers and wrappers you will quickly blow up your head.</p><p>The concept of PURISTA will help you in both cases. You simply follow the message flow. Check the input/output of the functions, and you will find the root cause quickly. You are able to follow single requests, because each one has a unique trace id all the way down. You can attach external providers and software solutions to track errors on each of your functions. You can track metrics on each of your functions.</p><h2 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to “Metrics”">​</a></h2><p>Collecting metrics becomes necessary at a certain scale.</p><p>Metrics should also be categorized into two big topics.</p><p>There are technical and functional metric values. Examples include time and resource consumption, failure and success counts, response times, and so on.</p><p>On the other side, you will have business-related metrics. This includes customer- and user-centric values. For example, active user count, daily active users, or average order amount.</p><h3 id="technical-metric-values" tabindex="-1">Technical metric values <a class="header-anchor" href="#technical-metric-values" aria-label="Permalink to “Technical metric values”">​</a></h3><p>For technical metric values, PURISTA tries to provide simple, first-class connectivity to standard third-party solutions. In most cases, this is just configuration.</p><h3 id="business-metric-values" tabindex="-1">Business metric values <a class="header-anchor" href="#business-metric-values" aria-label="Permalink to “Business metric values”">​</a></h3><p>When it comes to business metrics, things become more challenging, because this highly depends on your business, the metrics you want to collect, and the third-party solution you want to use for analysis. This means there cannot be an out-of-the-box solution for every need. But PURISTA can help you quickly aggregate the values you need because of its core concept.</p>',17)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
